// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading ensures readiness before frame 0
const { fontFamily: interFamily } = loadInter();



export type IMessageChatProps = Record<string, any>;

const IMessageChat: React.FC<IMessageChatProps> = ({
  backgroundColor = "#050505",
  transparentBackground = false,
  durationInSeconds = 15,
  dateText = "Reseñas Recientes",
  message1 = "Hice una reservación y nos dijeron que teníamos que sentarnos en el bar",
  message2 = "4 mesas vacías TODO el tiempo",
  message3 = "La anfitriona fue MUY grosera",
  accentColor = "#E74428",
  keyboardColor = "#111111",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background transparency logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timeline Configuration
  const script = [
    {
      text: message1,
      startTyping: 1 * fps,
      endTyping: 3 * fps,
      send: 3.5 * fps,
    },
    {
      text: message2,
      startTyping: 4.5 * fps,
      endTyping: 7 * fps,
      send: 7.5 * fps,
    },
    {
      text: message3,
      startTyping: 8.5 * fps,
      endTyping: 10 * fps,
      send: 10.5 * fps,
    },
  ];

  const ratingFrame = 11.5 * fps;

  // Derive State from Frame
  let currentInput = "iMessage";
  let isPlaceholder = true;
  const sentMessages = [];

  for (let i = 0; i < script.length; i++) {
    const item = script[i];
    
    // Check if message is sent
    if (frame >= item.send) {
      sentMessages.push({ ...item, id: i });
    } 
    // Check if message is currently being typed/held before sending
    else if (frame >= item.startTyping && frame < item.send) {
      isPlaceholder = false;
      if (frame < item.endTyping) {
        const charCount = Math.floor(
          interpolate(frame, [item.startTyping, item.endTyping], [0, item.text.length], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          })
        );
        currentInput = item.text.substring(0, charCount);
      } else {
        currentInput = item.text;
      }
    }
  }

  // Layout Measurements
  const keyboardHeight = height * 0.32; // ~614px
  const chatBottomOffset = keyboardHeight + 180; // Expanded to accommodate multiline input

  const row1 = ['Q','W','E','R','T','Y','U','I','O','P'];
  const row2 = ['A','S','D','F','G','H','J','K','L'];
  const row3 = ['Z','X','C','V','B','N','M'];

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily }}>
      
      {/* 1. Chat History Area */}
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          width: "100%",
          height: height - chatBottomOffset,
          display: "flex",
          flexDirection: "column",
          justifyContent: "flex-end",
          padding: "80px 40px 40px 40px",
          boxSizing: "border-box",
          gap: "24px",
          transition: "none",
        }}
      >
        {/* Date Header (Pill Style) */}
        <div style={{ textAlign: "center", marginBottom: "auto", marginTop: "40px" }}>
          <span style={{ 
            fontSize: "26px", 
            color: "#FFFFFF", 
            fontWeight: 600,
            backgroundColor: "#1C1C1E",
            padding: "10px 32px",
            borderRadius: "40px",
            boxShadow: "0 4px 16px rgba(0,0,0,0.5)",
            display: "inline-block"
          }}>
            {dateText}
          </span>
        </div>

        {/* Render Sent Messages */}
        {sentMessages.map((msg, index) => {
          const scale = spring({
            frame: frame - msg.send,
            fps,
            config: { damping: 14, stiffness: 120 },
          });

          return (
            <div
              key={msg.id}
              style={{
                alignSelf: "flex-end",
                maxWidth: "80%",
                backgroundColor: accentColor,
                padding: "24px 36px",
                borderRadius: "40px",
                borderBottomRightRadius: "8px",
                color: "#FFFFFF",
                fontSize: "36px",
                lineHeight: "1.4",
                transform: `scale(${scale})`,
                transformOrigin: "bottom right",
                position: "relative",
                boxShadow: "0 8px 24px rgba(231, 68, 40, 0.15)", // Subtle brand-colored shadow
                transition: "none",
              }}
            >
              {msg.text}

              {/* Message Tail SVG */}
              <svg 
                width="30" 
                height="30" 
                viewBox="0 0 30 30" 
                style={{ 
                  position: "absolute", 
                  right: -12, 
                  bottom: 0,
                  zIndex: -1
                }}
              >
                <path d="M 0 30 C 15 30 30 15 30 0 L 30 30 Z" fill={accentColor} />
              </svg>
            </div>
          );
        })}
      </div>

      {/* 2. Input Field Area */}
      <div
        style={{
          position: "absolute",
          bottom: keyboardHeight,
          left: 0,
          width: "100%",
          minHeight: 140,
          display: "flex",
          alignItems: "flex-end",
          padding: "30px 40px",
          boxSizing: "border-box",
          backgroundColor: backgroundColor,
          borderTop: `2px solid #1C1C1E`,
          transition: "none",
        }}
      >
        <div
          style={{
            flex: 1,
            minHeight: "80px",
            border: "3px solid #1C1C1E",
            borderRadius: "40px",
            display: "flex",
            alignItems: "flex-end",
            padding: "7px 7px 7px 20px",
            gap: "20px",
            backgroundColor: "#111111",
            boxSizing: "border-box",
          }}
        >
          {/* Mock Camera/App Icon */}
          <div style={{ 
            width: "40px", 
            height: "40px", 
            borderRadius: "20px", 
            backgroundColor: "#2C2C2E", 
            flexShrink: 0,
            marginBottom: "10px"
          }} />
          
          {/* Text Content */}
          <div
            style={{
              flex: 1,
              whiteSpace: "pre-wrap",
              wordBreak: "break-word",
              fontSize: "36px",
              lineHeight: "1.25",
              color: isPlaceholder ? "#545456" : "#FFFFFF",
              padding: "10px 0",
              marginBottom: "3px",
            }}
          >
            {currentInput}
          </div>

          {/* Send Button */}
          <div
            style={{
              width: "60px",
              height: "60px",
              borderRadius: "30px",
              backgroundColor: !isPlaceholder ? accentColor : "#2C2C2E",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              flexShrink: 0,
              transition: "none",
            }}
          >
            {/* Up Arrow SVG */}
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
              <path d="M12 20V4M12 4L5 11M12 4L19 11" stroke="#FFFFFF" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round"/>
            </svg>
          </div>
        </div>
      </div>

      {/* 3. Keyboard Mockup (Dark Mode) */}
      <div
        style={{
          position: "absolute",
          bottom: 0,
          left: 0,
          width: "100%",
          height: keyboardHeight,
          backgroundColor: keyboardColor,
          display: "flex",
          flexDirection: "column",
          padding: "30px 20px",
          boxSizing: "border-box",
          gap: "24px",
          transition: "none",
        }}
      >
        {/* Row 1 */}
        <div style={{ display: "flex", gap: "12px", height: "90px" }}>
          {row1.map((char, i) => (
            <div key={`r1-${i}`} style={keyStyle}>{char}</div>
          ))}
        </div>
        
        {/* Row 2 */}
        <div style={{ display: "flex", gap: "12px", height: "90px", padding: "0 40px" }}>
          {row2.map((char, i) => (
            <div key={`r2-${i}`} style={keyStyle}>{char}</div>
          ))}
        </div>
        
        {/* Row 3 */}
        <div style={{ display: "flex", gap: "12px", height: "90px" }}>
          <div style={{ ...keyStyle, flex: 1.5, backgroundColor: "#2C2C2E", fontSize: "40px" }}>⇧</div>
          {row3.map((char, i) => (
            <div key={`r3-${i}`} style={keyStyle}>{char}</div>
          ))}
          <div style={{ ...keyStyle, flex: 1.5, backgroundColor: "#2C2C2E", fontSize: "32px" }}>⌫</div>
        </div>
        
        {/* Row 4 */}
        <div style={{ display: "flex", gap: "12px", height: "90px" }}>
          <div style={{ ...keyStyle, flex: 2.5, backgroundColor: "#2C2C2E", fontSize: "28px" }}>123</div>
          <div style={{ ...keyStyle, flex: 5, fontSize: "28px" }}>space</div>
          <div style={{ ...keyStyle, flex: 2.5, backgroundColor: "#2C2C2E", fontSize: "28px" }}>return</div>
        </div>
      </div>

      {/* 4. Dramatic Star Rating Overlay */}
      {frame >= ratingFrame && (
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            backgroundColor: `rgba(0,0,0,${interpolate(frame, [ratingFrame, ratingFrame + 15], [0, 0.85], { extrapolateRight: "clamp" })})`,
            zIndex: 100,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              gap: "30px",
              padding: "50px 60px",
              backgroundColor: "#0A0A0A",
              borderRadius: "40px",
              border: "1px solid #222",
              boxShadow: "0 30px 60px rgba(0,0,0,0.8)",
              transform: `scale(${spring({ frame: frame - ratingFrame, fps, config: { damping: 14, stiffness: 100 } })})`,
            }}
          >
            <div style={{ fontSize: "36px", color: "#FFFFFF", fontWeight: 700, letterSpacing: "-0.5px" }}>
              Experiencia
            </div>
            <div style={{ display: "flex", gap: "16px" }}>
              {[0, 1, 2, 3, 4].map((starIdx) => {
                const starSpring = spring({
                  frame: frame - ratingFrame - (starIdx * 4),
                  fps,
                  config: { damping: 12, stiffness: 150 }
                });
                
                const isGlowing = starIdx === 0;
                
                return (
                  <div key={starIdx} style={{ transform: `scale(${starSpring})` }}>
                    <svg 
                      width="72" 
                      height="72" 
                      viewBox="0 0 24 24" 
                      fill={isGlowing ? "#FFB800" : "#222222"}
                      style={{
                        filter: isGlowing ? "drop-shadow(0px 0px 16px rgba(255, 184, 0, 0.6))" : "none"
                      }}
                    >
                      <path d="M12 17.27L18.18 21l-1.64-7.03L22 9.24l-7.19-.61L12 2 9.19 8.63 2 9.24l5.46 4.73L5.82 21z"/>
                    </svg>
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      )}
    </AbsoluteFill>
  );
};

// Dark mode key styling
const keyStyle: React.CSSProperties = {
  flex: 1,
  backgroundColor: "#363638",
  borderRadius: "12px",
  boxShadow: "0px 2px 0px 0px #000000",
  transition: "none",
  display: "flex",
  justifyContent: "center",
  alignItems: "center",
  fontSize: "32px",
  fontWeight: 400,
  color: "#FFFFFF",
};

export default IMessageChat;